  "knowledge": "Event ROI Potential (ERP)",
  "description": "Estimates the potential return on investment for inviting a fan to exclusive events",
  "definition": "ERP = FLV \\times \\left(\\frac{evtpart\\_numeric}{3}\\right) \\times \\left(\\frac{tierstep}{5}\\right) \\times \\left(1 + \\frac{inflscore}{100}\\right), \\text{ where evtpart\\_numeric maps participation\\_summary.event\\_attendance.evtpart enum values: Never=0, Rare=1, Regular=2, Always=3. Higher scores indicate fans likely to generate more value when included in events.}"
}

{
  "id": 33,
  "knowledge": "Tier Acceleration Factor (TAF)",
  "description": "Measures how quickly a fan is advancing through tier levels relative to platform norms",
  "definition": "TAF = \\frac{tierstep}{\\sqrt{membdays}} \\times \\frac{10}{\\sqrt{365}}, \\text{ normalized to annual scale for consistent comparison across fans with different membership durations.}"
}

{
  "id": 35,
  "knowledge": "Social Conversion Rate (SCR)",
  "description": "Measures a fan's ability to convert their social network into active platform participants",
  "definition": "SCR = \\frac{refcount}{(socialcommunity.community\\_engagement->>'network.follcount')::int} \\times 100, \\text{ expressed as a percentage of followers successfully converted to platform users.}"
}

{
  "id": 31,
  "knowledge": "Content Quality to Engagement Ratio (CQER)",
  "description": "Measures how a fan's content quality relates to their overall engagement",
  "definition": "CQER = \\frac{contqualrate}{engrate \\times 10}, \\text{ where values above 1.0 indicate fans producing content of quality higher than their general engagement level would predict.}"
}

{
  "id": 36,
  "knowledge": "Content Quality Consistency (CQC)",
  "description": "Measures the consistency of a fan's content quality relative to their engagement consistency",
  "definition": "CQC = contqualrate \\times intconsist \\times \\frac{ugcval}{10}, \\text{ where intconsist measures interaction consistency on a scale of 0-1.}"
}

{
  "id": 38,
  "knowledge": "Event Response Factor (ERF)",
  "description": "Measures a fan's response rate to official events and activities",
  "definition": "ERF = \\frac{(eventsandclub.participation\\_summary->>'event\\_attendance.onevtatt')::int + (eventsandclub.participation\\_summary->>'event\\_attendance.offevtatt')::int}{10} \\times \\left(1 + \\frac{FEI}{2}\\right), \\text{ where onevtatt and offevtatt represent online and offline events attended.}"
}

{
  "id": 39,
  "knowledge": "Churn Prevention Investment (CPI)",
  "description": "Calculates the optimal investment for preventing churn based on fan value and risk",
  "definition": "CPI = FLV \\times \\frac{RRF}{5} \\times 0.1, \\text{ suggesting investing up to 10\\% of at-risk value, scaled according to churn risk level.}"
}

