  "definition": "ERP = FLV \\times \\left(\\frac{evtpart\\_numeric}{3}\\right) \\times \\left(\\frac{tierstep}{5}\\right) \\times \\left(1 + \\frac{inflscore}{100}\\right), \\text{ where evtpart\\_numeric maps participation\\_summary.event\\_attendance.evtpart enum values: Never=0, Rare=1, Regular=2, Always=3. Higher scores indicate fans likely to generate more value when included in events.}"
}

{
  "id": 33,
  "knowledge": "Tier Acceleration Factor (TAF)",
  "description": "Measures how quickly a fan is advancing through tier levels relative to platform norms",
  "definition": "TAF = \\frac{tierstep}{\\sqrt{membdays}} \\times \\frac{10}{\\sqrt{365}}, \\text{ normalized to annual scale for consistent comparison across fans with different membership durations.}"
}

{
  "id": 35,
  "knowledge": "Social Conversion Rate (SCR)",
  "description": "Measures a fan's ability to convert their social network into active platform participants",
  "definition": "SCR = \\frac{refcount}{(socialcommunity.community\\_engagement->>'network.follcount')::int} \\times 100, \\text{ expressed as a percentage of followers successfully converted to platform users.}"
}

{
  "id": 31,
  "knowledge": "Content Quality to Engagement Ratio (CQER)",
  "description": "Measures how a fan's content quality relates to their overall engagement",
  "definition": "CQER = \\frac{contqualrate}{engrate \\times 10}, \\text{ where values above 1.0 indicate fans producing content of quality higher than their general engagement level would predict.}"
}

{
  "id": 36,
  "knowledge": "Content Quality Consistency (CQC)",
  "description": "Measures the consistency of a fan's content quality relative to their engagement consistency",
  "definition": "CQC = contqualrate \\times intconsist \\times \\frac{ugcval}{10}, \\text{ where intconsist measures interaction consistency on a scale of 0-1.}"
}

{
  "id": 38,
  "knowledge": "Event Response Factor (ERF)",
  "description": "Measures a fan's response rate to official events and activities",
  "definition": "ERF = \\frac{(eventsandclub.participation\\_summary->>'event\\_attendance.onevtatt')::int + (eventsandclub.participation\\_summary->>'event\\_attendance.offevtatt')::int}{10} \\times \\left(1 + \\frac{FEI}{2}\\right), \\text{ where onevtatt and offevtatt represent online and offline events attended.}"
}

{
  "id": 39,
  "knowledge": "Churn Prevention Investment (CPI)",
  "description": "Calculates the optimal investment for preventing churn based on fan value and risk",
  "definition": "CPI = FLV \\times \\frac{RRF}{5} \\times 0.1, \\text{ suggesting investing up to 10\\% of at-risk value, scaled according to churn risk level.}"
}

{
  "id": 49,
  "knowledge": "Gift-Focused Supporter",
  "description": "Identifies fans whose primary support comes through gifting rather than direct spending",
  "definition": "A fan with GIQ > 50 but spendusd < 100, showing a preference for gift-based support mechanisms over traditional subscription or purchase options."
}

{
  "id": 3,
  "knowledge": "membershipandspending.membkind",
  "description": "Explains the benefit differences between membership types",
  "definition": "'Free' users can access only basic content with approximately 10 hours of viewable content per month; 'Basic' members (about $5 monthly) receive reduced ads and access to additional content; 'Premium' members (about $10-15 monthly) get ad-free experience, exclusive content, and priority viewing; 'Diamond' members (above $25 monthly) receive all benefits plus 1-on-1 interaction opportunities and physical merchandise."
}

{
  "id": 1,
  "knowledge": "fans.tierstep",
  "description": "Explains the practical significance of fan tier levels",
  "definition": "Fan tiers (tierstep) start at 1 and increase progressively, representing different loyalty levels and privileges: Tiers 1-3 are 'Entry-level' fans (newly joined), tiers 4-7 represent 'Mid-level' fans (stable supporters), tiers 8-10 are 'High-level fans (long-term loyal followers), and tiers above 10 are 'Core' fans (foundational idol supporters). Any accounts with missing or invalid tier values are classified as 'Undefined' and require administrative review. Each tier level grants new privileges and increases platform visibility."
}

{
  "id": 7,
  "knowledge": "interactions.gifttot_interactions.giftvalusd",
  "description": "Explains the statistical significance of gift quantity and value",
  "definition": "gifttot represents the total number of gifts sent by fans, typically classified as: fewer than 10 is considered minimal gifting, 10-50 represents moderate support, and above 50 indicates substantial support; giftvalusd represents the USD value of gifts, generally $1-5 for small support, $5-20 for moderate support, $20-100 for large support, and above $100 for super support. Both metrics combined assess a fan's economic support level."
}

{
  "id": 11,
  "knowledge": "Monetization Value (MV)",
  "description": "Calculates the monetary value a fan brings to the platform over time",
  "definition": "MV = spendusd \\times \\left(1 + \\frac{membdays}{365} \\times 0.5\\right) \\times \\left(1 + \\frac{gifttot}{10} \\times 0.2\\right), \\text{ where the formula adjusts spending based on membership duration and gift activity to reflect long-term value.}"
}

{
  "id": 53,
  "knowledge": "Fan Value Segmentation",
  "description": "Classifies fans into value tiers based on their Fan Lifetime Value (FLV) relative to platform-wide percentiles",
  "definition": "Segments fans into four distinct value categories using percentile thresholds: 'Top Tier' identifies fans with FLV above the 90th percentile (p90), representing the platform's most valuable users; 'High Value' identifies fans with FLV between the 75th and 90th percentiles (p75 to p90); 'Medium Value' identifies fans with FLV between the 50th and 75th percentiles (median to p75); 'Low Value' applies to all fans with FLV below the median (p50). This segmentation enables targeted retention strategies, premium service offerings, and resource allocation based on projected economic contribution."
}

{
  "id": 19,
  "knowledge": "Support Efficiency Index (SEI)",
  "description": "Measures the efficiency of platform resources spent on supporting a fan",
  "definition": "SEI = \\frac{satrate}{(supptix + 1)} \\times \\left(1 + \\frac{FLV}{100}\\right), \\text{ where higher values indicate fans who provide good platform ratings with minimal support requirements, adjusted by their lifetime value.}"
}

{
  "id": 30,
  "knowledge": "Premium Engagement Ratio (PER)",
  "description": "Measures the relationship between fan spending and their engagement level",
  "definition": "PER = \\frac{MV}{FEI \\times 100}, \\text{ where higher values indicate fans who spend more relative to their engagement level.}"
}

{
  "id": 10,
  "knowledge": "Fan Engagement Index (FEI)",
  "description": "A comprehensive metric measuring fan activity level with platform and virtual idols",
  "definition": "FEI = (engrate \\times 0.4) + (\\frac{socintscore}{100} \\times 0.3) + (\\frac{actdayswk}{7} \\times 0.2) + (\\frac{avgsesscount}{10} \\times 0.1), \\text{ where weights reflect each factor's different contribution to engagement, with results ranging from 0-1. Higher values indicate more engaged fans.}"
}

{
  "id": 37,
  "knowledge": "Loyalty Value Ratio (LVR)",
  "description": "Evaluates the relationship between a fan's loyalty points and their economic value",
  "definition": "LVR = \\frac{loypts}{MV \\times 10}, \\text{ where higher values indicate fans accumulating loyalty faster than their spending would predict.}"
}

{
  "id": 16,
  "knowledge": "Fan Lifetime Value (FLV)",
  "description": "Projects the total economic value of a fan throughout their relationship with the platform",
  "definition": "FLV = MV \\times \\left(1 - \\frac{RRF}{10}\\right) \\times (1 + FEI) \\times 24, \\text{ estimating 24-month value adjusted by retention risk and engagement level.}"
}

{
  "id": 32,
  "knowledge": "Investment Recovery Period (IRP)",
  "description": "Estimates how many months it will take to recover platform investment in a fan",
  "definition": "IRP = \\frac{supptix \\times 30}{MV \\times (1 - \\frac{RRF}{10})}, \\text{ where supptix represents support tickets as a proxy for platform resources invested in the fan.}"
}

{
  "id": 12,
  "knowledge": "Content Creation Impact Score (CCIS)",
  "description": "Measures the impact of fan-created content on the community",
  "definition": "CCIS = contqualrate \\times \\left(\\frac{ugcval}{10}\\right) \\times \\left(1 + \\frac{follcount}{100} \\times 0.5\\right), \\text{ where content quality is multiplied by normalized content volume and amplified by follower reach.}"
}

{
  "id": 14,
  "knowledge": "Social Influence Multiplier (SIM)",
  "description": "Calculates how much a fan amplifies content through their social network",
  "definition": "SIM = \\left(\\frac{follcount}{100}\\right) \\times (engrate \\times 2) \\times (viralcont + 1) \\times 0.5, \\text{ reflecting the fan's ability to spread content through their network based on their following, engagement level, and history of creating viral content.}"
}

{
  "id": 15,
  "knowledge": "Loyalty Progression Rate (LPR)",
  "description": "Measures how quickly a fan is accumulating loyalty within the system",
  "definition": "LPR = \\left(\\frac{loypts}{membdays}\\right) \\times (1 + (engrate \\times 2)), \\text{ showing points earned per day adjusted by engagement level to identify rapidly advancing fans.}"
}

{
  "id": 13,
  "knowledge": "Retention Risk Factor (RRF)",
  "description": "Quantifies the risk of fan churn based on multiple behavioral indicators",
  "definition": "RRF = (1 - intconsist) \\times 2 + \\left(\\frac{CURRENT\\_DATE - lastlogdt}{30}\\right) \\times 0.5 + \\left(\\frac{churnflag\\_numeric}{3}\\right) \\times 2, \\text{ where churnflag\\_numeric maps churnflag enum: None=0, Low=1, Medium=2, High=3.}"
}

{
  "id": 17,
  "knowledge": "Community Contribution Index (CCI)",
  "description": "Measures a fan's overall contribution to the virtual idol community",
  "definition": "CCI = (CCIS \\times 0.4) + (SIM \\times 0.3) + (collabcount \\times 0.1) + (FEI \\times 0.2), \\text{ balancing content creation, social influence, collaboration activity, and general engagement.}"
}

